import { StyleSheet } from "@/registry/bases/takumi/lib/pdf-primitives";
import type { PdfcnTheme } from "@/registry/types/pdf-themes";

/**
 * Creates all list styles derived from the active theme.
 * @param t - The resolved PdfcnTheme instance.
 */
export const createListStyles = (t: PdfcnTheme) => {
  const { borderRadius, spacing, fontWeights, typography } = t.primitives;

  return StyleSheet.create({
    checkBox: {
      alignItems: "center",
      backgroundColor: t.colors.background,
      borderColor: t.colors.border,
      borderRadius: 3,
      borderStyle: "solid",
      borderWidth: 1.5,
      height: spacing[4],
      justifyContent: "center",
      marginRight: spacing[2],
      width: spacing[4],
    },
    checkBoxChecked: {
      backgroundColor: t.colors.success,
      borderColor: t.colors.success,
    },
    childrenContainer: {
      display: "flex",
      flexDirection: "column",
      marginLeft: spacing[5],
      marginTop: spacing[1],
    },
    container: {
      display: "flex",
      flexDirection: "column",
      marginBottom: t.spacing.componentGap,
      width: "100%",
    },
    descriptiveAccent: {
      backgroundColor: t.colors.primary,
      borderRadius: borderRadius.sm,
      marginRight: spacing[3],
      minHeight: spacing[4],
      width: 3,
    },
    descriptiveContent: {
      flex: 1,
    },
    descriptiveDesc: {
      color: t.colors.mutedForeground,
      fontFamily: t.typography.body.fontFamily,
      fontSize: typography.sm,
      lineHeight: t.typography.body.lineHeight,
      marginTop: 1,
    },
    descriptiveTitle: {
      color: t.colors.foreground,
      fontFamily: t.typography.body.fontFamily,
      fontSize: t.typography.body.fontSize,
      fontWeight: fontWeights.semibold,
      lineHeight: t.typography.body.lineHeight,
    },
    iconBox: {
      alignItems: "center",
      backgroundColor: t.colors.primary,
      borderRadius: borderRadius.md,
      height: spacing[5],
      justifyContent: "center",
      marginRight: spacing[2],
      width: spacing[5],
    },
    iconMark: {
      color: t.colors.primaryForeground,
      fontFamily: t.typography.body.fontFamily,
      fontSize: 9,
      fontWeight: fontWeights.bold,
    },
    itemRow: {
      alignItems: "flex-start",
      flexDirection: "row",
    },
    itemRowCenter: {
      alignItems: "center",
      flexDirection: "row",
    },
    itemRowGapMd: { marginBottom: spacing[3] },
    itemRowGapSm: { marginBottom: spacing[2] },
    itemRowGapXs: { marginBottom: spacing[1] },
    itemText: {
      // No flex here — Text nodes with flex shorthand get flexBasis:0, which causes
      // Yoga to under-measure multi-line text height → overlapping rows.
      // flex:1 must live on the wrapping View, not on the Text itself.
      color: t.colors.foreground,
      fontFamily: t.typography.body.fontFamily,
      fontSize: t.typography.body.fontSize,
      lineHeight: t.typography.body.lineHeight,
    },
    itemTextBold: {
      fontWeight: fontWeights.semibold,
    },
    itemTextSub: {
      // Same: no flex — see itemText comment.
      color: t.colors.mutedForeground,
      fontFamily: t.typography.body.fontFamily,
      fontSize: t.typography.body.fontSize - 0.5,
      lineHeight: t.typography.body.lineHeight,
    },
    itemTextWrap: {
      // Companion to itemText / itemTextSub. Apply this to the View that wraps
      // the Text so flex expansion happens at the View level, not the Text level.
      flex: 1,
    },
    markerBulletDot: {
      backgroundColor: t.colors.primary,
      borderRadius: 3,
      height: 5,
      width: 5,
    },
    markerBulletSubDot: {
      backgroundColor: "transparent",
      borderColor: t.colors.mutedForeground,
      borderRadius: 2,
      borderStyle: "solid",
      borderWidth: 1,
      height: 4,
      width: 4,
    },
    markerBulletSubWrap: {
      alignItems: "center",
      justifyContent: "flex-start",
      marginTop: spacing[1],
      width: spacing[4],
    },
    markerBulletWrap: {
      alignItems: "center",
      justifyContent: "flex-start",
      marginTop: spacing[1],
      width: spacing[4],
    },
    markerNumberBadge: {
      alignItems: "center",
      backgroundColor: t.colors.primary,
      borderRadius: spacing[5],
      height: spacing[5],
      justifyContent: "center",
      marginRight: spacing[2],
      width: spacing[5],
    },
    markerNumberText: {
      color: t.colors.primaryForeground,
      fontFamily: t.typography.body.fontFamily,
      fontSize: typography.xs,
      fontWeight: fontWeights.bold,
    },
  });
};

import type React from "react";

import {
  usePdfcnTheme,
  useSafeMemo,
} from "@/registry/bases/takumi/components/theme-provider";
import {
  View,
  Text as PDFText,
} from "@/registry/bases/takumi/lib/pdf-primitives";
import type { Style } from "@/registry/bases/takumi/lib/pdf-primitives";

import { createListStyles } from "./list.styles";
import type { ListItem, ListVariant, PdfListProps } from "./list.types";

type Styles = ReturnType<typeof createListStyles>;
type GapProp = "xs" | "sm" | "md";

const getGapStyle = (gap: GapProp, styles: Styles): Style => {
  if (gap === "xs") {
    return styles.itemRowGapXs;
  }
  if (gap === "md") {
    return styles.itemRowGapMd;
  }
  return styles.itemRowGapSm;
};

const buildRowStyles = (
  index: number,
  total: number,
  gap: GapProp,
  styles: Styles,
  align: "start" | "center" = "start"
): Style[] => {
  const row: Style[] = [
    align === "center" ? styles.itemRowCenter : styles.itemRow,
  ];
  if (index !== total - 1) {
    row.push(getGapStyle(gap, styles));
  }
  return row;
};

/** Bullet dot marker — solid filled for level 0, outline ring for nested levels. */
const dotMarker = (level: number, styles: Styles): React.ReactElement =>
  level === 0 ? (
    <View style={styles.markerBulletWrap}>
      <View style={styles.markerBulletDot} />
    </View>
  ) : (
    <View style={styles.markerBulletSubWrap}>
      <View style={styles.markerBulletSubDot} />
    </View>
  );

// eslint-disable-next-line no-use-before-define, prefer-const
let renderBulletItem: (
  item: ListItem,
  index: number,
  total: number,
  gap: GapProp,
  styles: Styles,
  level: number
) => React.ReactElement;
// eslint-disable-next-line no-use-before-define, prefer-const
let renderMultiLevelItem: (
  item: ListItem,
  index: number,
  total: number,
  gap: GapProp,
  styles: Styles,
  level: number
) => React.ReactElement;

const renderNumberedItem = (
  item: ListItem,
  index: number,
  total: number,
  gap: GapProp,
  styles: Styles
): React.ReactElement => (
  <View key={index} style={buildRowStyles(index, total, gap, styles, "center")}>
    <View style={styles.markerNumberBadge}>
      <PDFText style={styles.markerNumberText}>{`${index + 1}`}</PDFText>
    </View>
    <View style={styles.itemTextWrap}>
      <PDFText style={styles.itemText}>{item.text}</PDFText>
    </View>
  </View>
);

const renderChecklistItem = (
  item: ListItem,
  index: number,
  total: number,
  gap: GapProp,
  styles: Styles
): React.ReactElement => {
  const isChecked = item.checked ?? true;
  return (
    <View
      key={index}
      style={buildRowStyles(index, total, gap, styles, "center")}
    >
      <View
        style={[styles.checkBox, isChecked ? styles.checkBoxChecked : {}]}
      ></View>
      <View style={styles.itemTextWrap}>
        <PDFText style={styles.itemText}>{item.text}</PDFText>
      </View>
    </View>
  );
};

const renderIconItem = (
  item: ListItem,
  index: number,
  total: number,
  gap: GapProp,
  styles: Styles
): React.ReactElement => (
  <View key={index} style={buildRowStyles(index, total, gap, styles, "center")}>
    <View style={styles.iconBox}>
      <PDFText style={styles.iconMark}>★</PDFText>
    </View>
    <View style={styles.itemTextWrap}>
      <PDFText style={styles.itemText}>{item.text}</PDFText>
    </View>
  </View>
);

const renderDescriptiveItem = (
  item: ListItem,
  index: number,
  total: number,
  gap: GapProp,
  styles: Styles
): React.ReactElement => (
  <View key={index} style={buildRowStyles(index, total, gap, styles)}>
    <View style={styles.descriptiveAccent} />
    <View style={styles.descriptiveContent}>
      <PDFText style={styles.descriptiveTitle}>{item.text}</PDFText>
      {item.description ? (
        <PDFText style={styles.descriptiveDesc}>{item.description}</PDFText>
      ) : null}
    </View>
  </View>
);

const renderItem = (
  item: ListItem,
  index: number,
  total: number,
  variant: ListVariant,
  gap: GapProp,
  styles: Styles,
  level: number
): React.ReactElement | null => {
  switch (variant) {
    case "bullet": {
      return renderBulletItem(item, index, total, gap, styles, level);
    }
    case "numbered": {
      return renderNumberedItem(item, index, total, gap, styles);
    }
    case "checklist": {
      return renderChecklistItem(item, index, total, gap, styles);
    }
    case "icon": {
      return renderIconItem(item, index, total, gap, styles);
    }
    case "multi-level": {
      return renderMultiLevelItem(item, index, total, gap, styles, level);
    }
    case "descriptive": {
      return renderDescriptiveItem(item, index, total, gap, styles);
    }
    default: {
      break;
    }
  }
  return null;
};

const renderItemList = (
  items: ListItem[],
  variant: ListVariant,
  gap: GapProp,
  styles: Styles,
  level: number
): React.ReactElement => (
  <View style={level > 0 ? styles.childrenContainer : undefined}>
    {items.map((item, index) =>
      renderItem(item, index, items.length, variant, gap, styles, level)
    )}
  </View>
);

renderBulletItem = (item, index, total, gap, styles, level) => (
  <View key={index}>
    <View style={buildRowStyles(index, total, gap, styles)}>
      {dotMarker(level, styles)}
      <View style={styles.itemTextWrap}>
        <PDFText style={styles.itemText}>{item.text}</PDFText>
      </View>
    </View>
    {item.children && item.children.length > 0
      ? renderItemList(item.children, "bullet", gap, styles, level + 1)
      : null}
  </View>
);

renderMultiLevelItem = (item, index, total, gap, styles, level) => (
  <View key={index}>
    <View style={buildRowStyles(index, total, gap, styles)}>
      {dotMarker(level, styles)}
      <View style={styles.itemTextWrap}>
        <PDFText
          style={[
            level === 0 ? styles.itemText : styles.itemTextSub,
            level === 0 ? styles.itemTextBold : {},
          ]}
        >
          {item.text}
        </PDFText>
      </View>
    </View>
    {item.children && item.children.length > 0
      ? renderItemList(item.children, "multi-level", gap, styles, level + 1)
      : null}
  </View>
);

export const PdfList = ({
  items,
  variant = "bullet",
  gap = "sm",
  style,
  noWrap = false,
  _level = 0,
}: PdfListProps) => {
  const theme = usePdfcnTheme();
  const styles = useSafeMemo(() => createListStyles(theme), [theme]);

  const containerStyles: Style[] = [styles.container];
  if (_level > 0) {
    containerStyles.push(styles.childrenContainer);
  }
  const styleArray = style ? [...containerStyles, style] : containerStyles;

  return (
    <View wrap={!noWrap} style={styleArray}>
      {items.map((item, index) =>
        renderItem(item, index, items.length, variant, gap, styles, _level)
      )}
    </View>
  );
};

import type { Style } from "@/registry/bases/takumi/lib/pdf-primitives";

/** List visual style variant. */
export type ListVariant =
  | "bullet"
  | "numbered"
  | "checklist"
  | "icon"
  | "multi-level"
  | "descriptive";

/**
 * A single list item, optionally with nested children.
 * Props - `text` | `description` | `checked` | `children`
 * @see {@link ListItem}
 */
export interface ListItem {
  text: string;
  description?: string;
  checked?: boolean;
  children?: ListItem[];
}

/**
 * List of items with multiple style variants including bullet, numbered, checklist, and descriptive.
 * Props - `items` | `variant` | `gap` | `style` | `_level` | `noWrap`
 * @see {@link PdfListProps}
 */
export interface PdfListProps {
  items: ListItem[];
  /**
   * @default 'bullet'
   */
  variant?: ListVariant;
  /**
   * @default 'sm'
   */
  gap?: "xs" | "sm" | "md";
  style?: Style;
  _level?: number;
  /**
   * @default false
   */
  noWrap?: boolean;
}
